select oe1_0.id from orders oe1_0 left join customers r1_0 on r1_0.id=oe1_0.referrer_id where oe1_0.id<=? and exists(select 1 from customers ce1_0 where ce1_0.id<=? and (exists(select 1 from orders o1_0 where o1_0.status=r1_0.name and ce1_0.id=o1_0.customer_id) or ce1_0.id=?)) order by 1
select oe1_0.id from orders oe1_0 left join customers r1_0 on r1_0.id=oe1_0.referrer_id where oe1_0.id<=? and exists(select 1 from customers ce1_0 where ce1_0.id<=? and (exists(select 1 from orders o1_0 where exists(select 1 from order_items i1_0 where i1_0.product_code=r1_0.name and o1_0.id=i1_0.order_id) and ce1_0.id=o1_0.customer_id) or ce1_0.id=?)) order by 1
select oe1_0.id from orders oe1_0 left join customers r1_0 on r1_0.id=oe1_0.referrer_id where oe1_0.id<=? and exists(select 1 from customers ce1_0 where ce1_0.id<=? and not exists(select 1 from orders o1_0 where o1_0.status=r1_0.name and ce1_0.id=o1_0.customer_id)) order by 1
select oe1_0.id,(select count(*) from customers ce1_0 where ce1_0.id<=? and (exists(select 1 from orders o1_0 where o1_0.status=r1_0.name and ce1_0.id=o1_0.customer_id) or ce1_0.id=?)) from orders oe1_0 left join customers r1_0 on r1_0.id=oe1_0.referrer_id where oe1_0.id<=? order by 1
